{%- set CAT = ["TG","TE","SE","OA","FD","GP","OT"] -%}
{%- set CAT_FULL = {"TG":["Transport","Goods"],"TE":["Transport","Employee"],"SE":["Spares /","Engineering"],"OA":["Office /","Admin"],"FD":["Food",""],"GP":["Geeprint",""],"OT":["Other",""]} -%}
{%- set VEHICLES = ["KAP 466","KAY 635","KCB 430","KBQ 788","KBT 972"] -%}
{%- set DAYS = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"] -%}
{%- set DAY_FULL = {"Sun":"Sunday","Mon":"Monday","Tue":"Tuesday","Wed":"Wednesday","Thu":"Thursday","Fri":"Friday","Sat":"Saturday"} -%}
{%- set TYPE_CODE = {"Wage":"W","Overtime":"O","Piecework":"P","Commission":"C","Loan":"L"} -%}

{#- live child rows: exclude cancelled (void) so inline sums reconcile with doc.total_out -#}
{%- set VOUCH = doc.vouchers | rejectattr("cancelled") | list -%}
{%- set WAGES = doc.wages_entries | rejectattr("cancelled") | list -%}
{%- set LOANS = doc.loan_entries | rejectattr("cancelled") | list -%}
{%- set PARK = doc.parking_entries | rejectattr("cancelled") | list -%}
{%- set MISC = doc.misc_entries | rejectattr("cancelled") | list -%}

{%- set s = namespace(cat_in=0, voucher_out=0, pc=0, etr=0, used=0) -%}
{%- set s.cat_in = VOUCH | selectattr("cash_in") | sum(attribute="amount") -%}
{%- set s.voucher_out = VOUCH | rejectattr("cash_in") | sum(attribute="amount") -%}
{%- set s.pc = VOUCH | selectattr("pc_received") | list | length -%}
{%- set s.etr = VOUCH | selectattr("etr_received") | list | length -%}
{%- for v in VOUCH -%}{%- if v.voucher_no or v.recipient or (v.amount or 0) %}{% set s.used = s.used + 1 %}{% endif -%}{%- endfor -%}

{#- receipt coverage (rows with OUT spend only) -#}
{%- set rc = namespace(doc_n=0, doc_a=0, pc_n=0, pc_a=0, etr_n=0, etr_a=0, both_n=0, both_a=0, none_n=0, none_a=0) -%}
{%- for v in VOUCH -%}
  {%- if not v.cash_in and (v.amount or 0) > 0 -%}
    {%- set _amt = v.amount or 0 -%}
    {%- if v.pc_received and v.etr_received -%}
      {%- set rc.both_n = rc.both_n + 1 %}{% set rc.both_a = rc.both_a + _amt %}{% set rc.doc_n = rc.doc_n + 1 %}{% set rc.doc_a = rc.doc_a + _amt -%}
    {%- elif v.pc_received -%}
      {%- set rc.pc_n = rc.pc_n + 1 %}{% set rc.pc_a = rc.pc_a + _amt %}{% set rc.doc_n = rc.doc_n + 1 %}{% set rc.doc_a = rc.doc_a + _amt -%}
    {%- elif v.etr_received -%}
      {%- set rc.etr_n = rc.etr_n + 1 %}{% set rc.etr_a = rc.etr_a + _amt %}{% set rc.doc_n = rc.doc_n + 1 %}{% set rc.doc_a = rc.doc_a + _amt -%}
    {%- else -%}
      {%- set rc.none_n = rc.none_n + 1 %}{% set rc.none_a = rc.none_a + _amt -%}
    {%- endif -%}
  {%- endif -%}
{%- endfor -%}

{%- set pk = namespace(total=0) -%}
{%- set pk.total = PARK | sum(attribute="amount") -%}
{%- set park_days = (PARK | selectattr("amount") | map(attribute="day_idx") | list) -%}

{%- set mz = namespace(bike=0, fork=0) -%}
{%- set mz.bike = MISC | selectattr("kind","equalto","Bike Fuel") | sum(attribute="amount") -%}
{%- set mz.fork = MISC | selectattr("kind","equalto","Forklift") | sum(attribute="amount") -%}
{%- set bike_rows = (MISC | selectattr("kind","equalto","Bike Fuel") | selectattr("amount") | list) -%}
{%- set fork_rows = (MISC | selectattr("kind","equalto","Forklift") | selectattr("amount") | list) -%}

{%- set wl = namespace(wage=0, ot=0, piece=0, comm=0, all=0, loans=0, signed=0) -%}
{%- set wl.wage = WAGES | selectattr("entry_type","equalto","Wage") | sum(attribute="amount") -%}
{%- set wl.ot = WAGES | selectattr("entry_type","equalto","Overtime") | sum(attribute="amount") -%}
{%- set wl.piece = WAGES | selectattr("entry_type","equalto","Piecework") | sum(attribute="amount") -%}
{%- set wl.comm = WAGES | selectattr("entry_type","equalto","Commission") | sum(attribute="amount") -%}
{%- set wl.all = WAGES | sum(attribute="amount") -%}
{%- set wl.loans = LOANS | sum(attribute="amount_issued") -%}
{%- set wl.signed = LOANS | sum(attribute="amount_signed") -%}

{%- set wage_rows = (WAGES | selectattr("recipient") | list) + (WAGES | rejectattr("recipient") | selectattr("amount") | list) -%}
{%- set loan_rows = (LOANS | selectattr("recipient") | list) + (LOANS | rejectattr("recipient") | selectattr("amount_issued") | list) -%}

{#- Week runs SUNDAY -> SATURDAY (7 days), for ALL weeks. Roll week_ending forward to
   its Saturday (new sheets store Sat, historical store Fri) then back to the Sunday. -#}
{%- set _wd = frappe.utils.getdate(doc.week_ending) if doc.week_ending else None -%}
{%- set saturday = frappe.utils.add_days(doc.week_ending, ((5 - _wd.weekday()) % 7)) if _wd else None -%}
{%- set sunday = frappe.utils.add_days(saturday, -6) if saturday else None -%}

{#- cumulative loan ledger: every loan up to & incl. this week, all floats -#}
{%- set ledger = namespace(rows=[], issued=0, signed=0, ok=False) -%}
{%- if frappe is defined and frappe.get_all is defined and doc.week_ending -%}
  {%- set _try = namespace(rows=None) -%}
  {%- set _try.rows = frappe.get_all("Petty Cash Loan Entry", filters={"parenttype": "Petty Cash Sheet", "cancelled": 0}, fields=["parent","txn_date","recipient","staff_id","reason","amount_issued","amount_signed","paye"], order_by="txn_date asc, idx asc", limit_page_length=0, ignore_permissions=True) -%}
  {%- if _try.rows is not none -%}
    {%- set _parents = _try.rows | map(attribute="parent") | list -%}
    {%- set _sheets = frappe.get_all("Petty Cash Sheet", filters={"name": ["in", _parents]}, fields=["name","week_ending","float"], limit_page_length=0, ignore_permissions=True) if _parents else [] -%}
    {%- for r in _try.rows -%}
      {%- if (r.recipient or (r.amount_issued or 0) > 0 or (r.amount_signed or 0) > 0) -%}
        {%- set _sh = (_sheets | selectattr("name","equalto", r.parent) | list | first) if _sheets else None -%}
        {%- set _we = _sh.week_ending if _sh else None -%}
        {%- set _fl = _sh.float if _sh else "" -%}
        {%- if _we and _we <= doc.week_ending -%}
          {%- set _cur = (_sh.name == doc.name) -%}
          {%- set ledger.rows = ledger.rows + [{"week_ending": _we, "float": _fl, "txn_date": r.txn_date, "recipient": r.recipient, "staff_id": r.staff_id, "reason": r.reason, "amount_issued": r.amount_issued or 0, "amount_signed": r.amount_signed or 0, "paye": r.paye, "is_current": _cur}] -%}
          {%- set ledger.issued = ledger.issued + (r.amount_issued or 0) -%}
          {%- set ledger.signed = ledger.signed + (r.amount_signed or 0) -%}
          {%- set ledger.ok = True -%}
        {%- endif -%}
      {%- endif -%}
    {%- endfor -%}
    {%- set ledger.rows = ledger.rows | sort(attribute="float") | sort(attribute="week_ending") -%}
  {%- endif -%}
{%- endif -%}

<div class="pcws">
<style>
  .pcws { font-family: Arial, Helvetica, sans-serif; color:#000; font-size:13px; }
  /* width:100% + padding + border must not overflow the page, or the right-hand
     meta is clipped mid-word ("… · Shir") */
  .pcws .title-bar, .pcws .section-h, .pcws .code-legend, .pcws .empty-state { box-sizing:border-box; }
  /* display:table (not flex) — wkhtmltopdf's WebKit has no flexbox support */
  .pcws .title-bar { background:#2B3990; color:#fff; padding:8px 14px; font-weight:bold; font-size:15px; border:2px solid #000; display:table; width:100%; table-layout:fixed; }
  .pcws .title-bar > div { display:table-cell; vertical-align:middle; }
  .pcws .title-bar > div:first-child { width:52%; }
  .pcws .title-bar > div:last-child { text-align:right; }
  .pcws .title-bar .sub { font-size:13px; font-weight:normal; opacity:0.95; }
  .pcws table { width:100%; border-collapse:collapse; margin-top:4px; font-size:13px; table-layout:fixed; }
  .pcws th, .pcws td { border:1px solid #000; padding:5px 7px; vertical-align:middle; word-wrap:break-word; overflow-wrap:break-word; }
  .pcws th { background:#E8EAF0; color:#000; font-weight:bold; text-align:center; font-size:12px; line-height:1.15; }
  .pcws td.right, .pcws th.right { text-align:right; }
  .pcws td.center, .pcws th.center { text-align:center; }
  .pcws td.lbl { background:#F5F6FA; font-weight:bold; text-align:left; }
  .pcws th.lbl { background:#F5F6FA; color:#2B3990; text-align:left; }
  .pcws .cat-cell { background:#EEF1FA; }
  .pcws .in-cell { background:#E8F5E9; }
  .pcws tr.totals td { background:#E8EAF0; font-weight:bold; }
  .pcws tr.totals td.cat-cell { background:#EEF1FA; }
  .pcws tr.totals td.in-cell { background:#E8F5E9; }
  .pcws .hi { background:#FFF8E1; font-weight:bold; }
  .pcws td.pct { background:#E8EAF0; font-weight:bold; }
  /* category & vehicle breakdown: full navy header row */
  .pcws table.sumtbl thead th { background:#2B3990; color:#fff; font-size:12px; line-height:1.2; word-break:normal; overflow-wrap:normal; }
  /* voucher category navy sub-headers — must never break "Engineering" mid-word */
  .pcws th.catsub { background:#2B3990; color:#fff; font-size:10px; line-height:1.15; word-break:normal; word-wrap:normal; overflow-wrap:normal; }
  /* receipt-coverage tracker */
  .pcws table.receipt-tracker th { background:#2B3990; color:#fff; font-size:11px; line-height:1.2; padding:5px 8px; }
  .pcws table.receipt-tracker th .sub { display:block; font-weight:normal; font-size:9.5px; opacity:0.85; margin-top:2px; }
  .pcws table.receipt-tracker th.lbl { background:#F5F6FA; color:#2B3990; text-align:left; }
  .pcws table.receipt-tracker td.lbl { background:#F5F6FA; font-weight:bold; text-align:left; }
  .pcws table.receipt-tracker td.hi { background:#FFF0CC; font-weight:bold; }
  .pcws table.receipt-tracker th.hi { background:#B86B00; color:#fff; }
  .pcws .code-legend { background:#F5F6FA; padding:6px 12px; font-size:12px; border:1px solid #CBD2E0; margin-top:4px; }
  .pcws .code-legend .code { font-weight:bold; color:#2B3990; }
  .pcws .code-legend .red-code { font-weight:bold; color:#C00000; }
  .pcws .code-legend .sep { color:#BBB; margin:0 6px; }
  .pcws .code-legend .chip { display:inline-block; width:12px; height:12px; background:#FFF0CC; border:1px solid #B86B00; vertical-align:-2px; margin:0 3px; }
  .pcws .section-h { background:#2B3990; color:#fff; font-weight:bold; padding:6px 12px; font-size:14px; border:1px solid #000; margin-top:10px; }
  /* amber wash: OUT spend row with neither PC nor ETR */
  .pcws tr.missing-receipt td { background:#FFF0CC; }
  .pcws tr.missing-receipt td.cat-cell { background:#FFE8B0; }
  .pcws tr.missing-receipt td.in-cell { background:#F2EBC8; }
  .pcws tr.missing-receipt td:first-child { box-shadow: inset 4px 0 0 #B86B00; }
  .pcws .recon-two { display:table; width:100%; margin-top:6px; }
  .pcws .recon-two > div { display:table-cell; width:50%; vertical-align:top; }
  .pcws .recon-two > div:first-child { padding-right:6px; }
  .pcws .recon-two > div:last-child { padding-left:6px; }
  .pcws .recon-two h3 { margin:4px 0; color:#2B3990; font-size:14px; }
  .pcws .note { margin-top:8px; font-size:10px; color:#333; }
  .pcws .note .red { color:#C00000; font-weight:bold; }
  .pcws .empty-state { padding:24px; text-align:center; color:#888; font-style:italic; font-size:13px; border:1px dashed #CBD2E0; margin-top:6px; }
  .pcws .page-break { page-break-before: always; }
  @media print {
    .pcws table { page-break-inside:auto; }
    .pcws thead { display:table-header-group; }
    .pcws tfoot { display:table-row-group; }
    .pcws tr { page-break-inside:avoid; page-break-after:auto; }
    .pcws table.meta-strip, .pcws table.receipt-tracker, .pcws table.sumtbl, .pcws .recon-two > div { page-break-inside:avoid; }
    @page { size: A4 landscape; margin: 6mm; }
  }
</style>

{#- ============ PAGE 1: RECONCILIATION & SUMMARY COVER ============ -#}
<div class="title-bar">
  <div>VIMIT CONVERTERS LIMITED &nbsp;|&nbsp; <span class="sub">WEEKLY PETTY CASH &mdash; RECONCILIATION &amp; SUMMARY</span></div>
  <div class="sub">COVER SHEET &middot; Wk {{ doc.week_no }} &middot; {{ doc.float }} Float &middot; {{ frappe.utils.format_date(sunday, "dd MMM yyyy") if sunday else "" }} &ndash; {{ frappe.utils.format_date(saturday, "dd MMM yyyy") if saturday else "" }} &middot; {{ doc.custodian_name or doc.custodian or "" }}</div>
</div>

<table class="cover-meta">
  <colgroup><col style="width:12%"><col style="width:22%"><col style="width:36%"><col style="width:30%"></colgroup>
  <tr><th>WEEK NO</th><th>WEEK (SUN&ndash;SAT)</th><th>CUSTODIAN</th><th>OPENING BALANCE (KES)</th></tr>
  <tr>
    <td class="center">{{ doc.week_no }}</td>
    <td>{{ frappe.utils.format_date(sunday, "dd MMM yyyy") if sunday else "" }} &ndash; {{ frappe.utils.format_date(saturday, "dd MMM yyyy") if saturday else "" }}</td>
    <td>{{ doc.custodian_name or doc.custodian or "" }}</td>
    <td class="right">{{ "{:,.0f}".format(doc.opening_balance or 0) }}</td>
  </tr>
</table>

<div class="section-h">CATEGORY BREAKDOWN (from Voucher Register)</div>
<table class="sumtbl">
  <colgroup><col style="width:20%"><col style="width:9%"><col style="width:9%"><col style="width:9%"><col style="width:9%"><col style="width:9%"><col style="width:9%"><col style="width:9%"><col style="width:17%"></colgroup>
  <thead>
    <tr>
      <th class="lbl" style="text-align:left">VOUCHER REGISTER &mdash; BY CATEGORY</th>
      {% for c in CAT %}<th>{{ CAT_FULL[c][0] }}{% if CAT_FULL[c][1] %}<br>{{ CAT_FULL[c][1] }}{% endif %}</th>{% endfor %}
      <th>TOTAL</th>
    </tr>
  </thead>
  <tbody>
    <tr>
      <td class="lbl">Cash OUT (KES)</td>
      {% for c in CAT %}{% set catout = VOUCH | rejectattr("cash_in") | selectattr("category","equalto",c) | sum(attribute="amount") %}<td class="right">{{ "{:,.0f}".format(catout) if catout else "" }}</td>{% endfor %}
      <td class="right hi">{{ "{:,.0f}".format(s.voucher_out) if s.voucher_out else "" }}</td>
    </tr>
    <tr>
      <td class="lbl">Cash IN (KES) &mdash; refunds</td>
      <td colspan="7" style="text-align:right;background:#F5F6FA"></td>
      <td class="right hi">{{ "{:,.0f}".format(s.cat_in) if s.cat_in else "" }}</td>
    </tr>
    <tr>
      <td class="lbl">Vouchers / Receipts</td>
      <td colspan="7" style="text-align:right">PC slips: <strong>{{ s.pc }}</strong> &nbsp;&middot;&nbsp; ETR receipts: <strong>{{ s.etr }}</strong> &nbsp;&middot;&nbsp; rows used: <strong>{{ s.used }}</strong></td>
      <td></td>
    </tr>
    <tr>
      <td class="lbl">% of Voucher Spend</td>
      {% for c in CAT %}{% set catout = VOUCH | rejectattr("cash_in") | selectattr("category","equalto",c) | sum(attribute="amount") %}<td class="pct center">{% if s.voucher_out and s.voucher_out > 0 %}{{ ((catout / s.voucher_out) * 100)|round(0)|int }}%{% else %}&mdash;{% endif %}</td>{% endfor %}
      <td class="pct center" style="color:#2B3990">100%</td>
    </tr>
  </tbody>
</table>

<div class="section-h">VEHICLE BREAKDOWN (from Vehicle Sheet)</div>
<table class="sumtbl">
  <colgroup><col style="width:22%"><col style="width:11%"><col style="width:11%"><col style="width:11%"><col style="width:11%"><col style="width:11%"><col style="width:11%"><col style="width:12%"></colgroup>
  <thead>
    <tr>
      <th class="lbl" style="text-align:left">VEHICLE SHEET &mdash; BY VEHICLE</th>
      {% for vh in VEHICLES %}<th>{{ vh }}</th>{% endfor %}
      <th>BIKE</th>
      <th>FORKLIFT</th>
    </tr>
  </thead>
  <tbody>
    <tr>
      <td class="lbl">Weekly Spend (KES)</td>
      {% for vh in VEHICLES %}{% set vtot = PARK | selectattr("vehicle","equalto",vh) | sum(attribute="amount") %}<td class="right">{{ "{:,.0f}".format(vtot) if vtot else "" }}</td>{% endfor %}
      <td class="right">{{ "{:,.0f}".format(mz.bike) if mz.bike else "" }}</td>
      <td class="right hi">{{ "{:,.0f}".format(mz.fork) if mz.fork else "" }}</td>
    </tr>
  </tbody>
</table>

<div class="section-h">END OF WEEK RECONCILIATION</div>
<div class="recon-two">
  <div>
    <h3>CASH MOVEMENT</h3>
    <table>
      <colgroup><col style="width:65%"><col style="width:35%"></colgroup>
      <tr><td class="lbl">A. Opening Balance (start of week)</td><td class="right">{{ "{:,.0f}".format(doc.opening_balance or 0) }}</td></tr>
      <tr><td class="lbl">B. Grand Total Cash OUT (vouchers + vehicle + bike + forklift + wages + loans + commission)</td><td class="right">{{ "{:,.0f}".format(doc.total_out or 0) }}</td></tr>
      <tr><td class="lbl">C. Total Cash IN (refunds)</td><td class="right">{{ "{:,.0f}".format(doc.total_in or 0) }}</td></tr>
      <tr class="totals"><td class="lbl" style="background:#FFF8E1">D. EXPECTED CLOSING = A &minus; B + C</td><td class="right hi">{{ "{:,.0f}".format(doc.expected_close or 0) }}</td></tr>
    </table>
  </div>
  <div>
    <h3>PHYSICAL RECONCILIATION</h3>
    <table>
      <colgroup><col style="width:65%"><col style="width:35%"></colgroup>
      <tr><td class="lbl">E. Physical Cash Count (end of week)</td><td class="right">{{ "{:,.0f}".format(doc.cash_count_end or 0) }}</td></tr>
      <tr><td class="lbl">F. Sum of Open Vouchers (cash out)</td><td class="right"></td></tr>
      <tr class="totals"><td class="lbl" style="background:#FFF8E1">G. AUTHORISED FLOAT</td><td class="right hi">{{ "{:,.0f}".format(doc.authorised_float or 0) }}</td></tr>
      <tr class="totals"><td class="lbl" style="background:#FFF8E1">H. VARIANCE = E &minus; D</td><td class="right hi">{{ "{:,.0f}".format(doc.variance or 0) }}</td></tr>
    </table>
  </div>
</div>

<table style="margin-top:10px">
  <colgroup><col style="width:24%"><col style="width:9%"><col style="width:24%"><col style="width:9%"><col style="width:24%"><col style="width:10%"></colgroup>
  <thead>
    <tr><th>CUSTODIAN &mdash; PREPARED</th><th>DATE</th><th>FINANCE MANAGER &mdash; REVIEWED</th><th>DATE</th><th>CFO &mdash; APPROVED</th><th>DATE</th></tr>
  </thead>
  <tbody>
    <tr><td style="height:48px"></td><td></td><td></td><td></td><td></td><td></td></tr>
  </tbody>
</table>

{#- ============ PAGE 2: COMPACT DATA BODY (meta strip + voucher register) ============ -#}
<div class="page-break"></div>
<div class="title-bar">
  <div>VIMIT CONVERTERS LIMITED &nbsp;|&nbsp; <span class="sub">WEEKLY PETTY CASH &mdash; FILING COPY</span></div>
  <div class="sub">Wk {{ doc.week_no }} &middot; {{ doc.float }} Float &middot; {{ frappe.utils.format_date(sunday, "dd MMM yyyy") if sunday else "" }} &ndash; {{ frappe.utils.format_date(saturday, "dd MMM yyyy") if saturday else "" }} &middot; {{ doc.custodian_name or doc.custodian or "" }}</div>
</div>

<table class="meta-strip">
  <tr>
    <th>OPENING</th><th>VOUCHER OUT</th><th>VEHICLE</th><th>WAGES + LOANS</th><th>CASH IN</th>
    <th>TOTAL OUT</th><th>EXPECTED CLOSE</th><th>CASH COUNT</th><th>VARIANCE</th><th>AUTH FLOAT</th>
  </tr>
  <tr>
    <td class="right">{{ "{:,.0f}".format(doc.opening_balance or 0) }}</td>
    <td class="right">{{ "{:,.0f}".format(s.voucher_out) if s.voucher_out else "" }}</td>
    <td class="right">{{ "{:,.0f}".format(pk.total + mz.bike + mz.fork) if (pk.total + mz.bike + mz.fork) else "" }}</td>
    <td class="right">{{ "{:,.0f}".format(wl.all + wl.loans) if (wl.all + wl.loans) else "" }}</td>
    <td class="right">{{ "{:,.0f}".format(s.cat_in) if s.cat_in else "" }}</td>
    <td class="right">{{ "{:,.0f}".format(doc.total_out or 0) }}</td>
    <td class="right hi">{{ "{:,.0f}".format(doc.expected_close or 0) }}</td>
    <td class="right">{{ "{:,.0f}".format(doc.cash_count_end or 0) }}</td>
    <td class="right hi">{{ "{:,.0f}".format(doc.variance or 0) }}</td>
    <td class="right">{{ "{:,.0f}".format(doc.authorised_float or 0) }}</td>
  </tr>
</table>

<div class="section-h">VOUCHER REGISTER &nbsp;&middot;&nbsp; {{ s.used }} entries</div>

<table class="receipt-tracker">
  <thead>
    <tr>
      <th class="lbl">Receipt coverage</th>
      <th>Documented<span class="sub">PC &#10003; or ETR &#10003;</span></th>
      <th>PC slip only<span class="sub">most common</span></th>
      <th>ETR receipt only<span class="sub">vendor-issued</span></th>
      <th>Both &#10003;&#10003;<span class="sub">rare</span></th>
      <th class="hi">No receipt at all<span class="sub">amber rows below</span></th>
    </tr>
  </thead>
  <tbody>
    <tr>
      <td class="lbl">Rows with spend</td>
      <td class="center"><strong>{{ rc.doc_n }}</strong></td>
      <td class="center"><strong>{{ rc.pc_n }}</strong></td>
      <td class="center"><strong>{{ rc.etr_n }}</strong></td>
      <td class="center"><strong>{{ rc.both_n }}</strong></td>
      <td class="center hi"><strong>{{ rc.none_n }}</strong></td>
    </tr>
    <tr>
      <td class="lbl">KES amount</td>
      <td class="right">{{ "{:,.0f}".format(rc.doc_a) if rc.doc_a else "" }}</td>
      <td class="right">{{ "{:,.0f}".format(rc.pc_a) if rc.pc_a else "" }}</td>
      <td class="right">{{ "{:,.0f}".format(rc.etr_a) if rc.etr_a else "" }}</td>
      <td class="right">{{ "{:,.0f}".format(rc.both_a) if rc.both_a else "" }}</td>
      <td class="right hi">{{ "{:,.0f}".format(rc.none_a) if rc.none_a else "" }}</td>
    </tr>
  </tbody>
</table>

<div class="code-legend">
  <span class="code">TG</span> Transport-Goods <span class="sep">&middot;</span>
  <span class="code">TE</span> Transport-Employee <span class="sep">&middot;</span>
  <span class="code">SE</span> Spares/Engineering <span class="sep">&middot;</span>
  <span class="code">OA</span> Office/Admin <span class="sep">&middot;</span>
  <span class="code">FD</span> Food <span class="sep">&middot;</span>
  <span class="code">GP</span> Geeprint <span class="sep">&middot;</span>
  <span class="code">OT</span> Other <span class="sep">|</span>
  <span class="chip"></span> = row has spend but neither PC slip nor ETR receipt is ticked
</div>

<table class="vtbl">
  <colgroup>
    <col style="width:2.5%"><col style="width:6%"><col style="width:6.5%"><col style="width:13%">
    <col style="width:4.5%"><col style="width:4.5%"><col style="width:4.5%"><col style="width:4.5%"><col style="width:4.5%"><col style="width:4.5%"><col style="width:4.5%">
    <col style="width:6.5%">
    <col style="width:3%"><col style="width:3%">
    <col style="width:16%"><col style="width:8%">
  </colgroup>
  <thead>
    <tr>
      <th rowspan="2">#</th><th rowspan="2">DATE</th><th rowspan="2">VOUCHER NO</th><th rowspan="2">RECIPIENT</th>
      <th colspan="7" style="background:#C00000;color:#fff">OUT (KES) &mdash; by category code</th>
      <th rowspan="2" style="background:#1B5E20;color:#fff">IN (KES)</th>
      <th rowspan="2">PC</th><th rowspan="2">ETR</th>
      <th rowspan="2">NOTES</th><th rowspan="2">SIGN</th>
    </tr>
    <tr>
      {% for c in CAT %}<th class="catsub">{{ CAT_FULL[c][0] }}{% if CAT_FULL[c][1] %}<br>{{ CAT_FULL[c][1] }}{% endif %}</th>{% endfor %}
    </tr>
  </thead>
  <tbody>
    {% set vn = namespace(i=0) %}
    {% for v in VOUCH %}
    {% if v.voucher_no or v.recipient or v.amount or v.category %}
    {% set vn.i = vn.i + 1 %}
    {% set needs = (v.amount or 0) and not v.cash_in and not v.pc_received and not v.etr_received %}
    <tr {% if needs %}class="missing-receipt"{% endif %}>
      <td class="center">{{ vn.i }}</td>
      <td>{{ frappe.utils.format_date(v.txn_date, "dd/MM/yy") if v.txn_date else "" }}</td>
      <td>{{ v.voucher_no or "" }}</td>
      <td>{{ v.recipient or "" }}</td>
      {% for c in CAT %}<td class="cat-cell right">{% if (not v.cash_in) and v.category == c and v.amount %}{{ "{:,.0f}".format(v.amount) }}{% endif %}</td>{% endfor %}
      <td class="in-cell right">{% if v.cash_in and v.amount %}{{ "{:,.0f}".format(v.amount) }}{% endif %}</td>
      <td class="center">{% if v.pc_received %}&#10003;{% endif %}</td>
      <td class="center">{% if v.etr_received %}&#10003;{% endif %}</td>
      <td>{{ v.notes or "" }}</td>
      <td></td>
    </tr>
    {% endif %}
    {% endfor %}
    <tr class="totals">
      <td colspan="4" class="right">WEEKLY TOTALS &rarr;</td>
      {% for c in CAT %}{% set catout = VOUCH | rejectattr("cash_in") | selectattr("category","equalto",c) | sum(attribute="amount") %}<td class="cat-cell right">{{ "{:,.0f}".format(catout) if catout else "" }}</td>{% endfor %}
      <td class="in-cell right">{{ "{:,.0f}".format(s.cat_in) if s.cat_in else "" }}</td>
      <td colspan="4" class="right">Voucher sub-total: <strong>{{ "{:,.0f}".format(s.voucher_out) if s.voucher_out else "0" }}</strong> <span style="font-weight:normal;opacity:0.75">(grand total on recon page)</span></td>
    </tr>
  </tbody>
</table>

{#- ============ PAGE: VEHICLE EXPENSES ============ -#}
{% if pk.total or bike_rows or fork_rows %}
<div class="page-break"></div>
<div class="title-bar">
  <div>VIMIT CONVERTERS LIMITED &nbsp;|&nbsp; <span class="sub">VEHICLE EXPENSES</span></div>
  <div class="sub">Wk {{ doc.week_no }} &middot; {{ doc.float }} Float &middot; {{ frappe.utils.format_date(sunday, "dd MMM yyyy") if sunday else "" }} &ndash; {{ frappe.utils.format_date(saturday, "dd MMM yyyy") if saturday else "" }}</div>
</div>
<div class="section-h">VEHICLE EXPENSES</div>

{% if pk.total %}
<table>
  <thead>
    <tr><th>DAY</th><th>DATE</th>{% for vh in VEHICLES %}<th>{{ vh }}</th>{% endfor %}<th>DAILY</th></tr>
  </thead>
  <tbody>
    {% for di in range(7) %}
    {% set dn = DAYS[di] %}
    {% set dtot = PARK | selectattr("day_idx","equalto",dn) | sum(attribute="amount") %}
    {% set ddate = frappe.utils.add_days(sunday, di) if sunday else None %}
    <tr>
      <td class="center">{{ dn }}</td>
      <td>{{ frappe.utils.format_date(ddate, "dd/MM/yy") if ddate else "" }}</td>
      {% for vh in VEHICLES %}
        {% set vt = PARK | selectattr("day_idx","equalto",dn) | selectattr("vehicle","equalto",vh) | sum(attribute="amount") %}
        <td class="right">{{ "{:,.0f}".format(vt) if vt else "" }}</td>
      {% endfor %}
      <td class="right">{{ "{:,.0f}".format(dtot) if dtot else "" }}</td>
    </tr>
    {% endfor %}
    <tr class="totals">
      <td colspan="2" class="right">WEEK &rarr;</td>
      {% for vh in VEHICLES %}{% set vtot = PARK | selectattr("vehicle","equalto",vh) | sum(attribute="amount") %}<td class="right">{{ "{:,.0f}".format(vtot) if vtot else "" }}</td>{% endfor %}
      <td class="right">{{ "{:,.0f}".format(pk.total) if pk.total else "" }}</td>
    </tr>
  </tbody>
</table>
{% endif %}

{% if bike_rows or fork_rows %}
<table style="margin-top:4px">
  <colgroup><col style="width:16.6%"><col style="width:16.6%"><col style="width:16.6%"><col style="width:16.6%"><col style="width:16.6%"><col style="width:17%"></colgroup>
  <thead>
    <tr><th colspan="3">BIKE FUEL</th><th colspan="3">FORKLIFT</th></tr>
    <tr><th>Date</th><th>Amount</th><th>Sign</th><th>Date</th><th>Amount</th><th>Sign</th></tr>
  </thead>
  <tbody>
    {% set bf_max = [bike_rows|length, fork_rows|length]|max %}
    {% for i in range(bf_max) %}
    <tr>
      <td>{% if i < bike_rows|length and bike_rows[i].txn_date %}{{ frappe.utils.format_date(bike_rows[i].txn_date, "dd/MM/yy") }}{% endif %}</td>
      <td class="right">{% if i < bike_rows|length and bike_rows[i].amount %}{{ "{:,.0f}".format(bike_rows[i].amount) }}{% endif %}</td>
      <td></td>
      <td>{% if i < fork_rows|length and fork_rows[i].txn_date %}{{ frappe.utils.format_date(fork_rows[i].txn_date, "dd/MM/yy") }}{% endif %}</td>
      <td class="right">{% if i < fork_rows|length and fork_rows[i].amount %}{{ "{:,.0f}".format(fork_rows[i].amount) }}{% endif %}</td>
      <td></td>
    </tr>
    {% endfor %}
    <tr class="totals">
      <td class="right">Total</td><td class="right">{{ "{:,.0f}".format(mz.bike) if mz.bike else "" }}</td><td></td>
      <td class="right">Total</td><td class="right">{{ "{:,.0f}".format(mz.fork) if mz.fork else "" }}</td><td></td>
    </tr>
  </tbody>
</table>
{% endif %}
{% endif %}

{#- ============ PAGE: WAGES ============ -#}
{% if wage_rows %}
<div class="page-break"></div>
<div class="title-bar">
  <div>VIMIT CONVERTERS LIMITED &nbsp;|&nbsp; <span class="sub">WAGES</span></div>
  <div class="sub">Wk {{ doc.week_no }} &middot; {{ doc.float }} Float &middot; {{ frappe.utils.format_date(sunday, "dd MMM yyyy") if sunday else "" }} &ndash; {{ frappe.utils.format_date(saturday, "dd MMM yyyy") if saturday else "" }}</div>
</div>
<div class="section-h">WAGES &amp; LOANS &nbsp;&middot;&nbsp; {{ wage_rows|length }} entries</div>
<table>
  <colgroup><col style="width:3%"><col style="width:9%"><col style="width:6%"><col style="width:23%"><col style="width:26%"><col style="width:13%"><col style="width:14%"><col style="width:6%"></colgroup>
  <thead>
    <tr><th>#</th><th>Date</th><th>Type</th><th>Recipient</th><th>Reason / Ref</th><th>Amount</th><th>Sign</th><th>PAYE</th></tr>
  </thead>
  <tbody>
    {% set wn = namespace(i=0) %}
