    {% set wn.i = wn.i + 1 %}
    <tr>
      <td class="center">{{ wn.i }}</td>
      <td>{{ frappe.utils.format_date(w.txn_date, "dd/MM/yy") if w.txn_date else "" }}</td>
      <td class="center">{{ TYPE_CODE.get(w.entry_type, (w.entry_type or "")[:1]) }}</td>
      <td>{{ w.recipient or "" }}</td>
      <td>{{ w.reason or "" }}</td>
      <td class="right">{{ "{:,.0f}".format(w.amount) if w.amount else "" }}</td>
      <td></td>
      <td class="center">{% if w.paye %}Y{% endif %}</td>
    </tr>
    {% endfor %}
    <tr class="totals">
      <td colspan="5" class="right">Wages: <strong>{{ "{:,.0f}".format(wl.wage) }}</strong> &middot; OT: <strong>{{ "{:,.0f}".format(wl.ot) }}</strong> &middot; Piecework: <strong>{{ "{:,.0f}".format(wl.piece) }}</strong> &middot; Comm: <strong>{{ "{:,.0f}".format(wl.comm) }}</strong></td>
      <td class="right">{{ "{:,.0f}".format(wl.all) }}</td>
      <td colspan="2"></td>
    </tr>
  </tbody>
</table>

<table style="margin-top:4px">
  <colgroup><col style="width:25%"><col style="width:25%"><col style="width:25%"><col style="width:25%"></colgroup>
  <thead>
    <tr><th>PIECEWORK</th><th>CASUALS</th><th>OVERTIME</th><th>TRAVEL ALLOWANCE</th></tr>
  </thead>
  <tbody>
    <tr>
      <td class="right" style="height:22px">{{ "{:,.0f}".format(wl.piece) if wl.piece else "" }}</td>
      <td></td>
      <td class="right">{{ "{:,.0f}".format(wl.ot) if wl.ot else "" }}</td>
      <td></td>
    </tr>
  </tbody>
</table>
{% endif %}

{#- ============ PAGE: LOANS ISSUED THIS WEEK ============ -#}
{% if loan_rows %}
<div class="page-break"></div>
<div class="title-bar">
  <div>VIMIT CONVERTERS LIMITED &nbsp;|&nbsp; <span class="sub">LOANS ISSUED THIS WEEK</span></div>
  <div class="sub">Wk {{ doc.week_no }} &middot; {{ doc.float }} Float &middot; {{ frappe.utils.format_date(sunday, "dd MMM yyyy") if sunday else "" }} &ndash; {{ frappe.utils.format_date(saturday, "dd MMM yyyy") if saturday else "" }}</div>
</div>
<div class="section-h" style="margin-top:8px">LOANS ISSUED THIS WEEK &nbsp;&middot;&nbsp; {{ loan_rows|length }} entries</div>
