{#- ============ PAGE: LOAN LEDGER ============ -#}
{% if ledger.ok and ledger.rows %}
<div class="page-break"></div>
<div class="title-bar">
  <div>VCL PETTY CASH &mdash; LOAN LEDGER</div>
  <div class="sub">All loans as at {{ frappe.utils.format_date(saturday, "dd MMM yyyy") if saturday else "" }} &middot; previous + this week's additions</div>
</div>
<div class="section-h" style="margin-top:6px">FULL LOAN LIST &nbsp;&middot;&nbsp; {{ ledger.rows | length }} loans</div>
<table>
  <colgroup><col style="width:4%"><col style="width:10%"><col style="width:9%"><col style="width:9%"><col style="width:20%"><col style="width:7%"><col style="width:17%"><col style="width:11%"><col style="width:11%"><col style="width:5%"></colgroup>
  <thead>
    <tr><th>#</th><th>Week Ending</th><th>Float</th><th>Date</th><th>Recipient</th><th>Staff</th><th>Reason / Ref</th><th>Issued</th><th>Signed-off</th><th>PAYE</th></tr>
  </thead>
  <tbody>
    {% for r in ledger.rows %}
    <tr {% if r.is_current %}style="background:#FFF8E1"{% endif %}>
      <td class="center">{{ loop.index }}</td>
      <td>{{ frappe.utils.format_date(r.week_ending, "dd/MM/yy") if r.week_ending else "" }}{% if r.is_current %} <strong>(new)</strong>{% endif %}</td>
      <td class="center">{{ r.float }}</td>
      <td>{{ frappe.utils.format_date(r.txn_date, "dd/MM/yy") if r.txn_date else "" }}</td>
      <td>{{ r.recipient or "" }}</td>
      <td class="center">{{ r.staff_id or "" }}</td>
      <td>{{ r.reason or "" }}</td>
      <td class="right">{{ "{:,.0f}".format(r.amount_issued) if r.amount_issued else "" }}</td>
      <td class="right">{{ "{:,.0f}".format(r.amount_signed) if r.amount_signed else "" }}</td>
      <td class="center">{% if r.paye %}Y{% endif %}</td>
    </tr>
    {% endfor %}
    <tr class="totals">
      <td colspan="7" class="right">RUNNING TOTAL &rarr;</td>
      <td class="right hi">{{ "{:,.0f}".format(ledger.issued) }}</td>
      <td class="right hi">{{ "{:,.0f}".format(ledger.signed) }}</td>
      <td></td>
    </tr>
  </tbody>
</table>
<p class="note">
  <span class="red">NOTE:</span>
  Running list of every loan issued up to and including this week, across all floats. Highlighted rows
